content.content:
switch (expression) {
  case val1:
    statements
    break;
  case val2:
    statements
    break;
  default:
    statements
}

#include <stdio.h>

int main() {
    int num = 3;

    switch (num) {
        case 1:
            printf("One\n");
            break; 
        case 2:
            printf("Two\n");
            break; 
        case 3:
            printf("Three\n");
            break; 
        default:
            printf("Not 1, 2, or 3.\n");
    }
}

